CardSpoke_MODS.register('word-counter', {
  onLoad: function(ctx) {
    ctx.logger.info('Word Counter loaded');
  },
  onCardRender: function(ctx, card, element) {
    if (!card || !element) return;
    var existing = element.querySelector('.mod-word-count');
    if (existing) existing.remove();
    var text = (card.body || '') + ' ' + (card.title || '');
    var words = text.trim().split(/\s+/).filter(function(w) { return w.length > 0; }).length;
    var chars = text.trim().length;
    var badge = document.createElement('span');
    badge.className = 'mod-word-count';
    badge.textContent = words + ' words / ' + chars + ' chars';
    badge.title = 'Word and character count';
    element.appendChild(badge);
  },
  onDisable: function(ctx) {
    var badges = document.querySelectorAll('.mod-word-count');
    badges.forEach(function(b) { b.remove(); });
    ctx.logger.info('Word Counter disabled');
  }
});
